class PublicPulseChatService:
    """Token-scoped access to an owner's allowlisted Pulse report conversation."""

    @staticmethod
    def _conversation_owner_sub(row: PulseShareLink) -> str:
        actor = row.chat_shared_by_subject_id
        if not actor or not actor.strip():
            raise HTTPException(status_code=HTTPStatus.NOT_FOUND, detail="Assistant not found")
        return actor

    @staticmethod
    def _require_chat_row(
        *,
        session: Session,
        link: str,
        lock: bool = False,
    ) -> PulseShareLink:
        cleaned_link = link.strip()
        if not SHARE_LINK_PATTERN.fullmatch(cleaned_link):
            raise HTTPException(status_code=HTTPStatus.NOT_FOUND, detail="Assistant not found")
        statement = select(PulseShareLink).where(
            col(PulseShareLink.link) == cleaned_link,
            col(PulseShareLink.deleted_at).is_(None),
            col(PulseShareLink.share_assistant_chat).is_(True),
        )
        if lock:
            statement = statement.with_for_update()
        row = session.exec(statement).first()
        if row is None or not PublicPulseChatService._pulse_exists(session=session, row=row):
            raise HTTPException(status_code=HTTPStatus.NOT_FOUND, detail="Assistant not found")
        return row

    @staticmethod
    def _pulse_exists(*, session: Session, row: PulseShareLink) -> bool:
        if row.pulse_type == PulseShareLinkPulseType.LEGACY_SESSION.value:
            return (
                session.exec(
                    select(LegacySession.id).where(
                        col(LegacySession.id) == row.pulse_id,
                        col(LegacySession.deleted_at).is_(None),
                    )
                ).first()
                is not None
            )
        if row.pulse_type == PulseShareLinkPulseType.GOAL_NAVIGATION.value:
            return (
                session.exec(
                    select(GoalNavigationStudy.id).where(
                        col(GoalNavigationStudy.id) == row.pulse_id,
                        col(GoalNavigationStudy.deleted_at).is_(None),
                    )
                ).first()
                is not None
            )
        return False

