        *,
        link: str,
        projection: PublicPulseShareResponse,
        findings_run_id: uuid.UUID | None = None,
    ) -> PublicPulseAssistantResponse:
        if not projection.share_assistant_chat:
            raise HTTPException(status_code=HTTPStatus.NOT_FOUND, detail="Assistant not found")
        thread = PublicPulseChatService._load_or_create_thread(
            link=link,
            projection=projection,
            findings_run_id=findings_run_id,
        )
        return PublicPulseAssistantResponse(
            report_title=thread.report_title or "Pulse report",
            prompts=list(GENERIC_PROMPTS),
            thread_id=thread.id,
            messages=PublicPulseChatService._messages(thread.id),
        )

