it('includes Assistant chat in GrowthOS Discover links without a toggle', async () => {
  activeTheme.name = 'purple';
  sessionDetail.current = {
    automatedInsightSession: {
      id: 'growthos-assistant-session',
      name: 'GrowthOS Assistant share',
      source: 'wevo-pulse',
      type: 'experience',
      segments: [],
      linkedSessions: [],
    },
    tasks: {},
  };
  completionStatus.isFullyCompleted = true;
  createOrLoadShareUrlMock.mockReset();
  createOrLoadShareUrlMock.mockResolvedValue(
    'https://staging-app.wevo.ai/share/pulse/growthos-public?theme=growthos'
  );
  loadShareStateMock.mockReset();
  loadShareStateMock.mockResolvedValue({ shareAssistantChat: false });
  updateShareAssistantChatMock.mockClear();
  const container = document.createElement('div');
  document.body.appendChild(container);
  const root = createRoot(container);

  try {
    await act(async () => {
      root.render(
        <MemoryRouter initialEntries={['/pulse/sessions/growthos-assistant-session/findings']}>
          <Route path='/pulse/sessions/:pulseId/findings'>
            <PulseHeader />
          </Route>
        </MemoryRouter>
      );
    });

    await act(async () => {
      container.querySelector<HTMLButtonElement>('button[aria-label="Send to Discover"]')?.click();
      await Promise.resolve();
      await Promise.resolve();
      await Promise.resolve();
    });

    const dialog = document.body.querySelector<HTMLElement>('[role="dialog"]');
    expect(updateShareAssistantChatMock).toHaveBeenCalledWith(
      expect.objectContaining({ id: 'growthos-assistant-session' }),
      true
    );
    expect(
      dialog?.querySelector('[aria-label="Include Assistant chat in public share"]')
    ).toBeNull();
    expect(dialog?.textContent).toContain('hideAssistant=false');
  } finally {
    await act(async () => root.unmount());
    container.remove();
    activeTheme.name = 'classic';
    completionStatus.isFullyCompleted = false;
    createOrLoadShareUrlMock.mockReset();
    loadShareStateMock.mockReset();
    loadShareStateMock.mockResolvedValue({ shareAssistantChat: false });
    updateShareAssistantChatMock.mockClear();
  }
});

